python
def xorRegisterPeakTicket(readings):
    a=readings
    out=[]
    state=0
    for x in a:
        state^=x
        out.append(state)
    return max(out,default=0)


java
class Solution {
  public int xorRegisterPeakTicket(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
